// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _target, uint256 _value) public {
        // Bound _value to avoid out-of-gas issues
        _value = bound(_value, 0, address(c).balance);
        // Record the owner before the call
        address ownerBefore = c.owner();
        // Drive the call to sendMoney
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", _target, _value));
        // The rule: owner must not change regardless of success/failure
        assertTrue(ownerBefore == c.owner());
    }
}

